jsLib:
function zzKey(){
  return 'ge_js_validator_20';
}
function zzHome(){
  return 'https://www.zzbook.net/';
}
function zzJar(ck){
  try{
    var v = ck.getKey(zzHome(), zzKey());
    return v ? String(v) : '';
  }catch(e){ }
  return '';
}
function zzMint(jv, ck){
  var cached = zzJar(ck);
  var s = '';
  try{ s = String(jv.ajax(zzHome()) || ''); }catch(e){ s = ''; }
  if(s.indexOf('hotcontent') >= 0){
    return cached;
  }
  var m = s.match(/ge_js_validator_\d+=[^;"']+/);
  if(m){
    try{ ck.setCookie(zzHome(), m[0]); }catch(e){ }
    var i = m[0].indexOf('=');
    if(i > 0){ return m[0].substring(i + 1); }
  }
  return cached;
}
function zzHead(v){
  if(!v){ return ',{"webView":true,"webViewDelayTime":2500}'; }
  return ',{"headers":{"Cookie":"' + zzKey() + '=' + v + '"}}';
}
function zzGet(jv, ck, path){
  var u = 'https://www.zzbook.net' + path;
  var v = zzMint(jv, ck);
  try{ jv.log('[zzbook] get ' + path + ' ck=' + (v ? 'Y' : 'N')); }catch(e){ }
  return u + zzHead(v);
}
function zzPost(jv, ck){
  var v = zzMint(jv, ck);
  try{ jv.log('[zzbook] search ck=' + (v ? 'Y' : 'N')); }catch(e){ }
  var o = '{"method":"POST","body":"s={{key}}"';
  if(v){ o += ',"headers":{"Cookie":"' + zzKey() + '=' + v + '"}'; }
  else { o += ',"webView":true,"webViewDelayTime":2500'; }
  return 'https://www.zzbook.net/search.html,' + o + '}';
}
function zzToc(jv, ck, u){
  var v = zzMint(jv, ck);
  try{ jv.log('[zzbook] toc ck=' + (v ? 'Y' : 'N')); }catch(e){ }
  return String(u) + zzHead(v);
}
